def test_compute_u0_vs_julia():
    # originally, julia had some placeholder values that were removed (because unused). We remove them here:
    du = model.compute_du(julia_u, julia_p, julia_t)
    np.testing.assert_allclose(du, julia_du)

def test_solver():
    sol = solve_ivp(
            lambda t, u: model.compute_du(u, julia_p, t),
            julia_tspan_m,
            julia_u,
            method="Radau",
            vectorized=False,
        )
    assert sol.success


